  transform: translateY(20px);
  opacity: 0;
}

.mobile-nav.open a {
  transform: translateY(0);
  opacity: 1;
}

.mobile-nav a:hover {
  color: var(--text-primary);
  background: rgba(124, 58, 237, 0.1);
}

