* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    background: linear-gradient(135deg, #1a1a2e, #16213e, #0f3460);
    font-family: 'Segoe UI', sans-serif;
}

.clock-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 30px;
}

.clock {
    width: 250px;
    height: 250px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(10px);
    border: 4px solid rgba(255, 255, 255, 0.2);
    position: relative;
    box-shadow: 0 0 30px rgba(0, 0, 0, 0.3),
                inset 0 0 30px rgba(255, 255, 255, 0.05);
}

.hand {
    position: absolute;
    bottom: 50%;
    left: 50%;
    transform-origin: bottom;
    border-radius: 5px;
}

.hour-hand {
    width: 6px;
    height: 60px;
    background: #fff;
    margin-left: -3px;
}

.minute-hand {
    width: 4px;
    height: 80px;
    background: #e0e0e0;
    margin-left: -2px;
}

.second-hand {
    width: 2px;
    height: 90px;
    background: #e94560;
    margin-left: -1px;
}

.center-dot {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 12px;
    height: 12px;
    background: #e94560;
    border-radius: 50%;
    z-index: 10;
}

.numbers {
    position: absolute;
    width: 100%;
    height: 100%;
}

.numbers span {
    position: absolute;
    text-align: center;
    font-size: 14px;
    color: rgba(255, 255, 255, 0.8);
    transform: rotate(calc(30deg * var(--i)));
    width: 100%;
    height: 100%;
}

.numbers span b {
    display: block;
    margin-top: 15px;
    transform: rotate(calc(-30deg * var(--i)));
}

.digital {
    font-size: 2.5rem;
    color: #fff;
    background: rgba(255, 255, 255, 0.1);
    backdrop-filter: blur(10px);
    padding: 15px 30px;
    border-radius: 15px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    letter-spacing: 3px;
    font-weight: 300;
}

@media (max-width: 400px) {
    .clock {
        width: 200px;
        height: 200px;
    }
    .hour-hand { height: 50px; }
    .minute-hand { height: 65px; }
    .second-hand { height: 75px; }
    .digital { font-size: 1.8rem; padding: 10px 20px; }
}
